mapper.select:
select o.id, o.order_id, o.user_id, o.user_name, commodity_name, commodity_id,commodity_type, o.amount, pay_mode, pay_status, pay_time, o.create_by,
o.create_time, o.update_by, o.update_time, o.version, o.del_flag, o.org_id,qr_code,target_order_id,qr_code_expire_time,o.mer_id,o.invoice_status,o.cmb_order_id,o.team_json,
refund_order_id,refund_amount,refund_reason,refund_time,pay_method,audit_opinion,payment_proof_files,u.phonenumber as phoneNumber,if(i.issued_status=1,true,false) as hasInvoiced,
c.school_name as schoolName ,o.order_type,o.refund_status,o.pay_order_id,o.rel_amount
from order_info o
left join sys_user u on o.user_id = u.user_id
left join nationwide_college_info c on c.id = u.school
left join invoice_info i on o.order_id = i.order_id
where o.del_flag = '0'
and o.id like concat('%',#{id},'%') 
and o.id like concat("%",#{idStr},"%")
and o.user_id = #{userId}
 and o.order_id like concat('%',#{orderId},'%')
 and o.user_name like concat('%', #{userName}, '%')
 and commodity_name like concat('%', #{commodityName}, '%')
 and commodity_id = #{commodityId}
 and pay_mode = #{payMode}
 and pay_status = #{payStatus}
 and pay_time = #{payTime}
and u.phonenumber like concat('%',#{phoneNumber},'%')
and commodity_type = #{commodityType}
and pay_method = #{payMethod}
and target_order_id like concat('%',#{targetOrderId},'%')
and cmb_order_id like concat('%',#{cmbOrderId},'%')
and mer_id = #{merId}
and o.invoice_status = #{invoiceStatus}
and c.school_name like concat('%',#{schoolName},'%')

    and pay_time >= #{payStartTime}


    and pay_time <= #{payEndTime}


    and o.amount >= #{amountStart}


    and o.amount <= #{amountEnd}

order by create_time desc

